# 정답 위치 고르게 섞기(재현 가능한 시드) — OX는 순서 유지
import random
rng = random.Random(20261013)
for q in data["questions"]:
    if q["type"] == "OX":
        continue
    order = list(range(len(q["options"])))
    rng.shuffle(order)
    q["options"] = [q["options"][i] for i in order]
    q["answer"] = order.index(q["answer"])

